@RestController
@ConfigurationProperties(prefix = "app.service")
@RefreshScope
public class ServiceConfigurationController {

    private String timeout;
    private boolean featureEnabled;

    // Standard getters and setters required for binding
    public void setTimeout(String timeout) { this.timeout = timeout; }
    public void setFeatureEnabled(boolean featureEnabled) { this.featureEnabled = featureEnabled; }

    @GetMapping("/config")
    public ResponseEntity<String> getConfig() {
        return ResponseEntity.ok("Timeout: " + timeout + ", Feature: " + featureEnabled);
    }
}
